// Receives { callId, channel, startedAt, endedAt, transcript: [{role, content}] } from the bot
// when a call ends. Summarises with Claude and keeps the last 50 calls in static data.
// Swap the storage for a DB/CRM/email node when you have one.
const req = $input.first().json;
if (($env.TOOLS_SECRET || '') && req.headers['x-tools-secret'] !== $env.TOOLS_SECRET) return [];
const call = req.body || {};
const lines = (call.transcript || []).map(m => `${m.role === 'user' ? 'Caller' : 'Agent'}: ${m.content}`).join('\n');

let summary = '';
if (lines) {
  const res = await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://api.anthropic.com/v1/messages',
    headers: { 'x-api-key': $env.ANTHROPIC_API_KEY, 'anthropic-version': '2023-06-01' },
    body: {
      model: $env.CLAUDE_MODEL || 'claude-haiku-4-5',
      max_tokens: 300,
      messages: [{ role: 'user', content: `Summarise this call in 2-3 sentences, then list any follow-up actions.\n\n${lines}` }],
    },
    json: true,
  });
  summary = res.content.filter(b => b.type === 'text').map(b => b.text).join(' ').trim();
}

const store = $getWorkflowStaticData('global');
store.calls = [...(store.calls || []), { ...call, summary }].slice(-50);
return [{ json: { callId: call.callId, channel: call.channel, summary, turns: (call.transcript || []).length } }];
